 @Test void ordinaryMainExecutesModeBlockCommonTailAnimationHistoryAndTouchExactlyOnce()throws Exception{
  var f=actual();var pool=new CdObjectPool();var state=state(f,2,2,0,0);var env=environment(f);var before=pool.capture();var context=context(f,f.a().terrain(),before,OptionalInt.empty());
  var r=f.body().stepR31(state,env,context);assertEquals(CdPlayerBody.Boundary.MAIN_RETURN,r.body().boundary());assertTrue(r.body().modeBoundary().isPresent());
  var calls=calls(r.body());for(var c:List.of(CdPlayerBody.NativeCall.CHARGE_BEFORE_DISPATCH,CdPlayerBody.NativeCall.MODE,CdPlayerBody.NativeCall.R3_SPECIAL_BLOCK_COLLISION,CdPlayerBody.NativeCall.DISPLAY,CdPlayerBody.NativeCall.RECORD_POSITION,CdPlayerBody.NativeCall.ANIMATE,CdPlayerBody.NativeCall.R3_WATER_RETURN,CdPlayerBody.NativeCall.R3_SPECIAL_CHUNKS_RETURN))assertEquals(1,Collections.frequency(calls,c));
  assertTrue(calls.indexOf(CdPlayerBody.NativeCall.MODE)<calls.indexOf(CdPlayerBody.NativeCall.R3_SPECIAL_BLOCK_COLLISION));assertTrue(calls.indexOf(CdPlayerBody.NativeCall.R3_SPECIAL_BLOCK_COLLISION)<calls.indexOf(CdPlayerBody.NativeCall.DISPLAY));
  assertTrue(calls.indexOf(CdPlayerBody.NativeCall.RECORD_POSITION)<calls.indexOf(CdPlayerBody.NativeCall.ANIMATE));assertEquals(1,r.body().effects().stream().filter(CdPlayerBody.TouchScanCompleted.class::isInstance).count());
  assertEquals(4,r.body().state().history().index());assertEquals(state.rotationAngle(),r.body().state().rotationAngle());assertEquals(state.rotationDistance(),r.body().state().rotationDistance());assertEquals(before.slots(),pool.capture().slots());assertEquals(state.header(),r.body().state().header());assertEquals(state.timers().reset(),r.body().state().timers().reset());assertEquals(state.objectLinks(),r.body().state().objectLinks());
 }
