 @Test void destructiveHurtStagesRealChildFourSharedChunkWritesAndUsesThatImageForAirCollision()throws Exception{
  var f=actual();var p=new CdObjectPool();p.write(p.state(32).moveLong(CdObjectState.LongField.MAPPINGS,0x123456).moveWord(CdObjectState.WordField.X_FRACTION,0xA5A5));var input=constructedCurrent(f,0);var before=p.capture();var s=state(f,4,2,0,0);var r=f.body().stepR31(s,environment(f),context(f,input,before,OptionalInt.empty()));
  var places=r.body().effects().stream().filter(CdPlayerBody.R31PlaceBlock.class::isInstance).map(CdPlayerBody.R31PlaceBlock.class::cast).toList();assertEquals(4,places.size());assertEquals(List.of(0x60,0x50,0x50,0x60),places.stream().map(CdPlayerBody.R31PlaceBlock::xWord).toList());assertEquals(List.of(0x400,0x400,0x3F0,0x3F0),places.stream().map(CdPlayerBody.R31PlaceBlock::yWord).toList());
  for(var place:places){assertTrue(place.chunkByteOffset().isPresent());assertEquals(0,r.nativeValues().terrain().chunks().unsignedWord(place.chunkByteOffset().orElseThrow()));}
  assertEquals(0x29,r.nativeValues().snapshot().slots().getFirst().id());assertEquals(0x60,r.nativeValues().snapshot().slots().getFirst().centreX());assertEquals(0x400,r.nativeValues().snapshot().slots().getFirst().centreY());assertEquals(0x123456,r.nativeValues().snapshot().slots().getFirst().longBits(CdObjectState.LongField.MAPPINGS));assertEquals(0xA5A5,r.nativeValues().snapshot().slots().getFirst().word(CdObjectState.WordField.X_FRACTION));assertEquals(before.slots(),p.capture().slots());assertEquals(OptionalInt.of(0),r.nativeValues().noBumperByte());
  assertTrue(r.body().effects().stream().anyMatch(e->e instanceof CdPlayerBody.R31SubCpuRequest q&&q.nativeId()==0x92));
  var air=r.body().effects().stream().filter(CdPlayerBody.R31AirCollisionImage.class::isInstance).map(CdPlayerBody.R31AirCollisionImage.class::cast).findFirst().orElseThrow();assertSame(r.nativeValues().terrain(),air.terrain());assertNotSame(input,air.terrain());var block=r.body().effects().stream().filter(CdPlayerBody.R31BlockCall.class::isInstance).map(CdPlayerBody.R31BlockCall.class::cast).findFirst().orElseThrow();assertEquals(2,block.result().state().actor().motion().routine());assertEquals(120,block.result().state().actor().timers().hurt());assertEquals(0,block.result().state().actor().motion().xVelocity());assertEquals(-0x700,block.result().state().actor().motion().yVelocity());assertEquals(block.result().state().actor().motion(),air.before());
  var independently=CdPlayerMovement.withR31CurrentTerrain(f.source(),air.terrain()).collideInAir(air.before(),air.environment());assertEquals(independently,air.result());
 }
