 static record Fixture(CdR31aAssets a,CdStagePlayerSource source,CdPlayerBody body){}
 private static Fixture cached;private static String cachedRoot;
 static synchronized Fixture actual()throws Exception{String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original USA CD source absent");if(cached!=null&&root.equals(cachedRoot))return cached;var usa=Path.of(root).resolve("USA");assertTrue(Files.isDirectory(usa),"Configured source must exist");List<Path> cues;try(var files=Files.list(usa)){cues=files.filter(p->p.toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();}assertEquals(1,cues.size());try(var programs=CdProgramAssets.open(cues.getFirst(),Optional.of(CdReleaseVariant.USA),Optional.empty())){var a=CdR31aAssets.fromPrograms(programs,CdStagePayload.R31A.stage());var source=CdStagePlayerSource.fromR31aAssets(a);cached=new Fixture(a,source,CdPlayerBody.fromStageSource(source));}cachedRoot=root;return cached;}
