 static CdStageTerrain constructedCurrent(Fixture f,int listIndex)throws java.io.IOException{var t=f.a().terrain();byte[] fg=f.a().view(CdR31aAssets.Asset.LAYOUT_FG).copy(),bg=f.a().view(CdR31aAssets.Asset.LAYOUT_BG).copy();for(int n=2;n<2+t.layout().columns(CdStageTerrain.Plane.FOREGROUND)*t.layout().rows(CdStageTerrain.Plane.FOREGROUND);n++)fg[n]=1;byte[] chunks=t.chunks().copy();int id=f.a().view(CdR31aAssets.Asset.PLAYER_BLOCKS_A).unsignedWord(2+listIndex*2)|0x6000;for(int at=0;at<512;at+=2){chunks[at]=(byte)(id>>>8);chunks[at+1]=(byte)id;}var col=t.collision();return CdStageTerrain.decode(t.shape(),t.blocks().copy(),t.patterns().copy(),chunks,fg,bg,col.ids().copy(),col.angles().copy(),col.heights().copy(),col.widths().copy());}
